[{"order":1,"type":"heading","text":"Authentication & Authorization Context in Firebase Firestore Security Rules"},{"order":2,"type":"paragraph","text":"Firebase Firestore Security Rules rely heavily on the request context to determine whether a user can read or write data. Understanding how to evaluate the request.auth object is essential for building secure applications."},{"order":3,"type":"subheading","text":"The request.auth Object"},{"order":4,"type":"paragraph","text":"When a client makes a request to Firestore while authenticated via Firebase Authentication, the request.auth variable is automatically populated. If the user is unauthenticated, this variable evaluates to null."},{"order":5,"type":"bullet_point","text":"request.auth.uid: The unique user ID string assigned by Firebase Auth."},{"order":6,"type":"bullet_point","text":"request.auth.token: A map containing JSON Web Token (JWT) claims, such as email, email_verified, and custom claims."},{"order":7,"type":"subheading","text":"Basic Authentication Check"},{"order":8,"type":"paragraph","text":"The most fundamental security rule is ensuring that a user is signed in before they can interact with a collection. You can achieve this by checking if request.auth is not null."},{"order":9,"type":"code","text":"rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /posts/{postId} {
      allow read, write: if request.auth != null;
    }
  }
}"},{"order":10,"type":"subheading","text":"Implementing User-Specific Authorization"},{"order":11,"type":"paragraph","text":"Authentication only verifies who the user is. Authorization determines what they are allowed to do. A common pattern is ensuring that users can only modify documents that belong to them, typically by matching the document ID or a field inside the document to request.auth.uid."},{"order":12,"type":"code","text":"rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /users/{userId} {
      allow read, write: if request.auth != null && request.auth.uid == userId;
    }
  }
}"},{"order":13,"type":"subheading","text":"Using Custom Claims for Role-Based Access Control"},{"order":14,"type":"paragraph","text":"For advanced authorization logic, such as administrative privileges, you can assign custom claims to users via the Firebase Admin SDK. These claims are then accessed inside your security rules via request.auth.token."},{"order":15,"type":"code","text":"rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /adminContent/{docId} {
      allow read, write: if request.auth != null && request.auth.token.admin == true;
    }
  }
}"}]
